print("-" * 40)
for k, value in results.items():
    print(f"{k:2} | {value}")

import math
def check_k_fourth_power(N):
    for k in range(-10, 11):
        if k**4 == N:
            return k
    return None

N = 88
solution = check_k_fourth_power(N)
print(f"Integer solution for k^4 = {N}: {solution}")
